const DQ = String.fromCharCode(34);
const MAX_VARIANTS = 4;
const src = $input.first().json;
const splitList = (v) => String(v || "").split(",").map((s) => s.trim()).filter((s) => s.length > 0);
const concepts = splitList(src.conceptTerms);
const synonyms = splitList(src.synonymTerms);
const cpc = String(src.cpc || "").trim();
const before = String(src.dateBefore || "").trim();
const dateClause = before ? (" and pd within " + DQ + "19000101 " + before + DQ) : "";
const phrase = (field, term) => field + " all " + DQ + term + DQ;
const keyword = [];
const classified = [];
let n = 0;
for (const c of concepts) {
  for (const s of synonyms) {
    n += 1;
    keyword.push({ variantId: "kw-" + n, kind: "keyword", terms: c + " + " + s, cql: phrase("ta", c) + " and " + phrase("ta", s) + dateClause });
  }
}
if (cpc) {
  let m = 0;
  for (const s of synonyms) {
    m += 1;
    classified.push({ variantId: "cls-" + m, kind: "classification", terms: cpc + " + " + s, cql: phrase("cpc", cpc) + " and " + phrase("ta", s) + dateClause });
  }
}
const out = [];
const half = Math.max(1, Math.floor(MAX_VARIANTS / 2));
const kwTake = classified.length > 0 ? Math.min(keyword.length, MAX_VARIANTS - Math.min(classified.length, half)) : Math.min(keyword.length, MAX_VARIANTS);
for (let i = 0; i < kwTake; i++) { out.push({ json: keyword[i] }); }
for (let j = 0; j < classified.length && out.length < MAX_VARIANTS; j++) { out.push({ json: classified[j] }); }
if (out.length === 0) { throw new Error("No query variants could be built. Supply at least one concept term and one synonym term."); }
return out;

const plan = $("Build Query Plan").all();
const req = $("Prior Art Request").first().json || {};
const responses = $input.all();
const seen = {};
const seeds = [];
const variantLog = [];
const DQ = String.fromCharCode(34);
const asArray = (v) => (v === undefined || v === null) ? [] : (Array.isArray(v) ? v : [v]);
const normId = (raw) => {
  let s = String(raw || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
  s = s.replace(/[A-Z]\d?$/, "");
  const m = s.match(/^([A-Z]{2})(\d+)$/);
  if (!m) { return s; }
  const cc = m[1];
  let num = m[2];
  if (cc === "US" && num.length === 10 && (num.slice(0, 2) === "19" || num.slice(0, 2) === "20")) {
    num = num.slice(0, 4) + num.slice(4).padStart(7, "0");
  }
  return cc + num;
};

const cpcRaw = String(req.cpc || "").trim();
const firstConcept = String(req.conceptTerms || "").split(",")[0].trim();
const broadenCql = cpcRaw ? ("cpc all " + DQ + cpcRaw + DQ) : (firstConcept ? ("ta all " + DQ + firstConcept + DQ) : "");
const broadenKind = cpcRaw ? "classification sweep" : "single-concept sweep (no CPC supplied)";

const classify = (raw) => {
  const status = Number(raw.statusCode || 0);
  const body = (raw.body !== undefined) ? raw.body : raw;
  let text = "";
  if (typeof body === "string") { text = body; }
  else if (body && typeof body.data === "string") { text = body.data; }
  if (text && text.indexOf("<fault") !== -1) {
    const m = text.match(/<code>([^<]+)<\/code>/);
    const code = m ? m[1] : "UNKNOWN.Fault";
    if (code === "SERVER.EntityNotFound") { return { state: "empty", code: code, status: status, body: null }; }
    return { state: "error", code: code, status: status, body: null };
  }
  if (text) { return { state: "error", code: "NON_JSON_RESPONSE", status: status, body: null }; }
  if (status && (status < 200 || status >= 300)) {
    if (status === 404) { return { state: "empty", code: "http-404", status: status, body: null }; }
    return { state: "error", code: "http-" + status, status: status, body: null };
  }
  return { state: "ok", code: "", status: status, body: body };
};

for (let i = 0; i < responses.length; i++) {
  const raw = responses[i].json || {};
  const meta = (plan[i] && plan[i].json) ? plan[i].json : { variantId: "unknown-" + i, kind: "unknown", cql: "" };
  const c = classify(raw);
  let total = 0;
  let added = 0;
  if (c.state === "ok") {
    const search = ((c.body["ops:world-patent-data"] || {})["ops:biblio-search"]) || {};
    total = parseInt(search["@total-result-count"] || "0", 10) || 0;
    const docs = asArray(((search["ops:search-result"] || {})["exchange-documents"]));
    for (const d of docs) {
      const ed = (d || {})["exchange-document"] || d || {};
      const country = ed["@country"];
      const docNumber = ed["@doc-number"];
      if (!country || !docNumber) { continue; }
      const pub = String(country) + String(docNumber);
      if (seen[pub]) { continue; }
      seen[pub] = true;
      added += 1;
      seeds.push({ publicationNumber: pub, normalizedId: normId(pub), kindCode: ed["@kind"] || "", foundBy: meta.variantId, foundByKind: meta.kind, foundByQuery: meta.cql });
    }
  }
  variantLog.push({ variantId: meta.variantId, kind: meta.kind, cql: meta.cql, state: c.state, faultCode: c.code, httpStatus: c.status, totalReported: total, newSeeds: added, zeroResult: c.state === "empty", errored: c.state === "error" });
}

const zeroCount = variantLog.filter((v) => v.zeroResult).length;
const errCount = variantLog.filter((v) => v.errored).length;
return [{ json: { seedCount: seeds.length, seeds: seeds, variantLog: variantLog, zeroResultVariants: zeroCount, erroredVariants: errCount, totalVariants: variantLog.length, broadenCql: broadenCql, broadenKind: broadenKind } }];

const src = $input.first().json || {};
const seeds = Array.isArray(src.seeds) ? src.seeds : [];
const rank = (pub) => {
  const cc = String(pub || "").slice(0, 2).toUpperCase();
  if (cc === "WO") { return 0; }
  if (cc === "EP") { return 1; }
  if (cc === "US") { return 2; }
  if (cc === "GB" || cc === "DE" || cc === "FR" || cc === "CA" || cc === "AU") { return 3; }
  return 4;
};
const ordered = seeds.map((s, i) => ({ s: s, i: i, r: rank(s.publicationNumber) }));
ordered.sort((a, b) => (a.r - b.r) || (a.i - b.i));
return ordered.slice(0, 4).map((o) => ({ json: Object.assign({}, o.s, { seedRank: o.r }) }));

const asArray = (v) => (v === undefined || v === null) ? [] : (Array.isArray(v) ? v : [v]);
const clean = (s) => { const t = String(s); return (t === "undefined" || t === "null" || t === "[object Object]") ? "" : t; };
const text = (v) => { if (v === undefined || v === null) { return ""; } if (typeof v === "string") { return clean(v); } if (typeof v === "object" && v.$ !== undefined) { return clean(v.$); } return clean(v); };
const normId = (raw) => {
  let s = String(raw || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
  s = s.replace(/[A-Z]\d?$/, "");
  const m = s.match(/^([A-Z]{2})(\d+)$/);
  if (!m) { return s; }
  const cc = m[1];
  let num = m[2];
  if (cc === "US" && num.length === 10 && (num.slice(0, 2) === "19" || num.slice(0, 2) === "20")) {
    num = num.slice(0, 4) + num.slice(4).padStart(7, "0");
  }
  return cc + num;
};
const rows = [];
const seenCite = {};
for (const item of $input.all()) {
  const raw = item.json || {};
  const body = (raw.body !== undefined) ? raw.body : raw;
  if (typeof body === "string" || (body && typeof body.data === "string")) { continue; }
  const docs = asArray(((body["ops:world-patent-data"] || {})["exchange-documents"] || {})["exchange-document"]);
  for (const ed of docs) {
    const seedPub = String(ed["@country"] || "") + String(ed["@doc-number"] || "");
    const biblio = ed["bibliographic-data"] || {};
    const titles = asArray(biblio["invention-title"]);
    let seedTitle = "";
    for (const t of titles) { if (!seedTitle || t["@lang"] === "en") { seedTitle = text(t); } }
    const refs = asArray((biblio["references-cited"] || {})["citation"]);
    for (const c of refs) {
      if (!c || typeof c !== "object") { continue; }
      const cat = asArray(c["category"]).map(text).join("");
      const patcit = c["patcit"];
      const nplcit = c["nplcit"];
      const phase = text(c["@cited-phase"]);
      let citedId = "";
      let citedKind = "";
      if (patcit) {
        const docIds = asArray(patcit["document-id"]);
        for (const di of docIds) {
          if (di["@document-id-type"] === "docdb" || !citedId) {
            citedId = text(di["country"]) + text(di["doc-number"]) + text(di["kind"]);
          }
        }
        citedKind = "patent";
      } else if (nplcit) {
        citedId = text(nplcit["text"]);
        citedKind = "npl";
      }
      if (!citedId) { continue; }
      const key = citedKind + "::" + citedId;
      const existing = seenCite[key];
      if (existing) {
        if (existing.citedBySeeds.indexOf(seedPub) === -1) { existing.citedBySeeds.push(seedPub); }
        if (phase && existing.citedPhases.indexOf(phase) === -1) { existing.citedPhases.push(phase); }
        continue;
      }
      const shortNpl = citedKind === "npl" ? (citedId.length > 160 ? citedId.slice(0, 160) + "..." : citedId) : "";
      const row = { source: "epo-examiner-citation", recordType: citedKind, id: citedId, normalizedId: citedKind === "patent" ? normId(citedId) : ("NPL::" + citedId.slice(0, 80)), title: shortNpl, examinerCategory: cat || "", citedPhases: phase ? [phase] : [], citedBySeeds: [seedPub], seedTitle: seedTitle, url: citedKind === "patent" ? ("https://worldwide.espacenet.com/patent/search?q=" + encodeURIComponent(citedId)) : "" };
      seenCite[key] = row;
      rows.push(row);
    }
  }
}
return rows.map((r) => ({ json: r }));

const raw = $input.first().json || {};
const asArray = (v) => (v === undefined || v === null) ? [] : (Array.isArray(v) ? v : [v]);
const normId = (rawId) => {
  let s = String(rawId || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
  s = s.replace(/[A-Z]\d?$/, "");
  const m = s.match(/^([A-Z]{2})(\d+)$/);
  if (!m) { return s; }
  const cc = m[1];
  let num = m[2];
  if (cc === "US" && num.length === 10 && (num.slice(0, 2) === "19" || num.slice(0, 2) === "20")) {
    num = num.slice(0, 4) + num.slice(4).padStart(7, "0");
  }
  return cc + num;
};
const rank = (pub) => {
  const cc = String(pub || "").slice(0, 2).toUpperCase();
  if (cc === "WO") { return 0; }
  if (cc === "EP") { return 1; }
  if (cc === "US") { return 2; }
  if (cc === "GB" || cc === "DE" || cc === "FR" || cc === "CA" || cc === "AU") { return 3; }
  return 4;
};
const body = (raw.body !== undefined) ? raw.body : raw;
let text = "";
if (typeof body === "string") { text = body; }
else if (body && typeof body.data === "string") { text = body.data; }
if (text) { return []; }
const search = ((body["ops:world-patent-data"] || {})["ops:biblio-search"]) || {};
const docs = asArray(((search["ops:search-result"] || {})["exchange-documents"]));
const seen = {};
const seeds = [];
for (const d of docs) {
  const ed = (d || {})["exchange-document"] || d || {};
  const country = ed["@country"];
  const docNumber = ed["@doc-number"];
  if (!country || !docNumber) { continue; }
  const pub = String(country) + String(docNumber);
  if (seen[pub]) { continue; }
  seen[pub] = true;
  seeds.push({ publicationNumber: pub, normalizedId: normId(pub), kindCode: ed["@kind"] || "", foundBy: "broadened-sweep", foundByKind: "classification", foundByQuery: "cpc sweep after zero keyword results" });
}
const ordered = seeds.map((s, i) => ({ s: s, i: i, r: rank(s.publicationNumber) }));
ordered.sort((a, b) => (a.r - b.r) || (a.i - b.i));
return ordered.slice(0, 4).map((o) => ({ json: Object.assign({}, o.s, { seedRank: o.r }) }));

const body = $input.first().json || {};
const ran = Array.isArray(body.results);
const errText = ran ? "" : String(body.error || body.message || "no results array in the response");
const results = ran ? body.results : [];

const out = results.map((w) => ({ json: {
  source: "openalex",
  recordType: "npl",
  id: String(w.id || ""),
  title: String(w.title || ""),
  year: w.publication_year || null,
  venue: ((w.primary_location || {}).source || {}).display_name || "",
  citedByCount: w.cited_by_count || 0,
  url: String(w.doi || w.id || ""),
  licenceFlag: "OpenAlex data is CC0; the underlying articles are not. Check each source before reuse."
} }));

// Always emit a status record. A leg that ran and matched nothing has ANSWERED;
// without this the report node can only infer "ran" from "produced rows", which
// reports a legitimate zero as a source that failed to run.
out.push({ json: {
  source: "openalex",
  recordType: "diagnostic",
  id: "openalex-status",
  title: "OpenAlex status",
  ran: ran,
  status: ran ? (results.length > 0 ? "ok" : "empty") : "errored",
  returned: results.length,
  reason: ran
    ? (results.length > 0 ? "" : "OpenAlex ran and matched zero records for the supplied terms. Zero is an answer, not a failure.")
    : ("OpenAlex did not return a usable response, so it was not searched: " + errText),
  url: ""
} });

return out;

const search = $("PubMed Search").first().json || {};
const esr = search.esearchresult || null;
const searchRan = !!esr;
const idlist = esr && Array.isArray(esr.idlist) ? esr.idlist : [];

const body = $input.first().json || {};
const result = body.result || {};
const uids = Array.isArray(result.uids) ? result.uids : [];

const out = uids.map((uid) => {
  const r = result[uid] || {};
  return { json: {
    source: "pubmed",
    recordType: "npl",
    id: "PMID:" + String(uid),
    title: String(r.title || ""),
    year: String(r.pubdate || "").slice(0, 4),
    venue: String(r.source || ""),
    url: "https://pubmed.ncbi.nlm.nih.gov/" + String(uid) + "/",
    licenceFlag: "PubMed records are public domain; the underlying articles are not."
  } };
});

// Status is taken from the esearch step, not from how many rows came out of
// esummary. A biomedical database answering zero to non-biomedical vocabulary
// is the correct answer, and must not be reported as a source that did not run.
let status;
let reason;
if (!searchRan) {
  status = "errored";
  reason = "The PubMed esearch call did not return a usable response, so PubMed was not searched: " + String(search.error || search.message || "no error text");
} else if (idlist.length === 0) {
  status = "empty";
  reason = "PubMed ran and matched zero records for the supplied terms. Zero is an answer, not a failure. This leg is driven by the same concept and synonym terms as the patent legs, and those terms are frequently not biomedical vocabulary - a mechanical or materials disclosure matching nothing here is expected. On this path the esummary call is still issued with an empty id list and is refused by NCBI; that refusal is expected and is not evidence of a fault.";
} else if (uids.length === 0) {
  status = "errored";
  reason = "PubMed esearch matched " + idlist.length + " record(s), but the esummary call returned none of them, so their details are missing from this run.";
} else {
  status = "ok";
  reason = "";
}

out.push({ json: {
  source: "pubmed",
  recordType: "diagnostic",
  id: "pubmed-status",
  title: "PubMed status",
  ran: status !== "errored",
  status: status,
  matched: idlist.length,
  returned: uids.length,
  reason: reason,
  url: ""
} });

return out;

const request = $("Prior Art Request").first().json || {};
const collected = $("Collect Seed Publications").first().json || {};
const rows = $input.all().map((i) => i.json || {});

const diagnostics = rows.filter((r) => r.recordType === "diagnostic");
const hitRows = rows.filter((r) => r.recordType !== "diagnostic");

const allowed = {};
for (const r of hitRows) { if (r.id) { allowed[String(r.id)] = true; } }
const seeds = Array.isArray(collected.seeds) ? collected.seeds : [];
for (const s of seeds) { allowed[String(s.publicationNumber)] = true; }

const kept = [];
const dropped = [];
for (const r of hitRows) {
  if (r.id && allowed[String(r.id)]) { kept.push(r); } else { dropped.push({ reason: "identifier not present in any retrieval payload", record: r }); }
}

const rawPatents = kept.filter((r) => r.recordType === "patent");
const nplHits = kept.filter((r) => r.recordType === "npl");
const bqHits = kept.filter((r) => r.source === "bigquery-us-fulltext");
const bqSkip = diagnostics.filter((d) => d.id === "bigquery-skipped")[0] || null;

const seedsExpandedSet = {};
for (const r of kept) {
  const cbs = Array.isArray(r.citedBySeeds) ? r.citedBySeeds : [];
  for (const s of cbs) { if (s) { seedsExpandedSet[String(s)] = true; } }
}
const seedsExpanded = Object.keys(seedsExpandedSet);

const byNorm = {};
const patentHits = [];
let mergedAcrossLegs = 0;
for (const r of rawPatents) {
  const key = String(r.normalizedId || r.id);
  const existing = byNorm[key];
  if (!existing) {
    const row = Object.assign({}, r);
    row.sources = [r.source];
    row.alsoSeenAs = [];
    byNorm[key] = row;
    patentHits.push(row);
    continue;
  }
  if (existing.sources.indexOf(r.source) === -1) { existing.sources.push(r.source); mergedAcrossLegs += 1; }
  if (String(r.id) !== String(existing.id) && existing.alsoSeenAs.indexOf(String(r.id)) === -1) { existing.alsoSeenAs.push(String(r.id)); }
  if (!existing.title && r.title) { existing.title = r.title; }
  if (!existing.examinerCategory && r.examinerCategory) { existing.examinerCategory = r.examinerCategory; }
}

const variantLog = Array.isArray(collected.variantLog) ? collected.variantLog : [];
const zeroVariants = variantLog.filter((v) => v.zeroResult);
const errVariants = variantLog.filter((v) => v.errored);
const faultCodes = [];
for (const v of errVariants) { if (v.faultCode && faultCodes.indexOf(v.faultCode) === -1) { faultCodes.push(v.faultCode); } }
const allErrored = variantLog.length > 0 && errVariants.length === variantLog.length;
const allMissed = variantLog.length > 0 && zeroVariants.length === variantLog.length;
const broadened = seeds.length === 0;
const nV = variantLog.length;
const variantWord = nV === 1 ? "query variant" : "query variants";

const opsOk = errVariants.length < variantLog.length;
const citationOk = kept.filter((r) => r.source === "epo-examiner-citation").length > 0;
const openAlexStatus = diagnostics.filter((d) => d.id === "openalex-status")[0] || null;
const pubmedStatus = diagnostics.filter((d) => d.id === "pubmed-status")[0] || null;
// "Ran" means the source answered, NOT that it returned rows. Deriving it from the
// kept-row count reports a legitimate zero as a source that did not run - which is
// the one thing this report exists to tell apart. Fall back to the old inference
// only if a status record is absent.
const openAlexOk = openAlexStatus ? openAlexStatus.ran === true : kept.filter((r) => r.source === "openalex").length > 0;
const pubmedOk = pubmedStatus ? pubmedStatus.ran === true : kept.filter((r) => r.source === "pubmed").length > 0;
const openAlexEmpty = openAlexStatus ? openAlexStatus.status === "empty" : false;
const pubmedEmpty = pubmedStatus ? pubmedStatus.status === "empty" : false;

const sourcesRun = [];
if (opsOk) { sourcesRun.push("EPO OPS (bibliographic search)"); }
if (citationOk) { sourcesRun.push("EPO OPS (examiner-cited references)"); }
if (openAlexOk) { sourcesRun.push("OpenAlex"); }
if (pubmedOk) { sourcesRun.push("PubMed"); }
if (!bqSkip) { sourcesRun.push("Google patents-public-data (US claims full text, BigQuery)"); }

const sourcesNotRun = [];
if (!opsOk) { sourcesNotRun.push("EPO OPS bibliographic search"); }
if (bqSkip) { sourcesNotRun.push("BigQuery US claims full text"); }
if (!openAlexOk) { sourcesNotRun.push("OpenAlex"); }
if (!pubmedOk) { sourcesNotRun.push("PubMed"); }

const sourcesZeroResult = [];
if (openAlexEmpty) { sourcesZeroResult.push("OpenAlex"); }
if (pubmedEmpty) { sourcesZeroResult.push("PubMed"); }

let runVerdict;
if (allErrored) {
  runVerdict = "UNRELIABLE - every EPO OPS query failed. This run searched no patent data. Re-run before drawing any conclusion.";
} else if (allMissed) {
  runVerdict = "DEGRADED - every keyword and classification variant returned zero results. Any patent art below came from the fallback sweep (" + String(collected.broadenKind || "fallback") + "), not from your search terms. The non-patent legs used those same terms and their results are UNVALIDATED - check them before relying on any of this.";
} else if (sourcesNotRun.length > 0 || errVariants.length > 0 || zeroVariants.length > 0) {
  runVerdict = "PARTIAL - " + (sourcesNotRun.length > 0 ? ("sources that did not run: " + sourcesNotRun.join("; ") + ". ") : "") + (zeroVariants.length > 0 ? (zeroVariants.length + " of " + nV + " " + variantWord + " returned zero results. ") : "") + "Recall on this run is incomplete; see coverage.knownGaps.";
} else if (sourcesZeroResult.length > 0) {
  runVerdict = "COMPLETE - all configured sources answered and every query variant returned results. " + sourcesZeroResult.join(" and ") + " answered with zero records, which is an answer and not a failure; see coverage.sourcesZeroResult.";
} else {
  runVerdict = "COMPLETE - all configured sources answered and every query variant returned results.";
}

const gaps = [];
if (errVariants.length > 0) { gaps.push("EPO OPS FAILED on " + errVariants.length + " of " + nV + " queries (" + faultCodes.join(", ") + "). Those queries returned NO ANSWER - not an empty answer."); }
if (allMissed) { gaps.push("EVERY query variant returned zero results. The OpenAlex and PubMed legs are driven by the SAME concept and synonym terms, so on a run like this their output is not corroborated by anything and has been observed returning plainly off-topic literature. Treat the non-patent list as unvalidated."); }
else if (zeroVariants.length > 0) { gaps.push(zeroVariants.length + " of " + nV + " " + variantWord + " returned zero results - that vocabulary missed, which is not evidence that no art exists."); }
if (bqSkip) { gaps.push("US claims full text was NOT searched on this run - see coverage.bigQuery."); }
if (sourcesZeroResult.length > 0) { gaps.push(sourcesZeroResult.join(" and ") + " ran and matched zero records. The non-patent legs are driven by the SAME concept and synonym terms as the patent search, and those terms are often not biomedical or scholarly vocabulary. A zero here reflects that mismatch, not an absence of literature."); }
gaps.push("Only " + nV + " " + variantWord + " and up to 4 citation seeds were run, to stay inside the caller timeout and the EPO fair-use limits. A deeper sweep needs a direct workflow run, not an MCP call.");
gaps.push("EPO OPS searches title and abstract only (field ta). A document whose abstract uses different vocabulary is invisible to keyword search and reachable only via classification or citation.");
gaps.push("OPS full text serves EP and WO; it does not serve US full text.");
gaps.push("BigQuery covers US full text only, and only for CPC areas with a subset built.");
gaps.push("No foreign-language original-text search; machine-translated abstracts only where available.");
gaps.push("No commercial database coverage (no Derwent, no chemical structure search, no sequence homology).");
gaps.push("Nothing here scores relevance. Every row was returned by an API for the terms supplied; none has been judged against the asserted novelty.");

return [{ json: {
  runVerdict: runVerdict,
  scopeLimitation: "FIRST-LOOK / KNOCK-OUT SEARCH ONLY. This is not a clearance, validity, freedom-to-operate or patentability opinion, and it is not a substitute for a professional searcher. It is educational and creates no attorney-client relationship.",
  assertedNovelty: String(request.disclosure || ""),
  coverage: {
    runAt: new Date().toISOString(),
    sourcesRun: sourcesRun,
    sourcesNotRun: sourcesNotRun,
    sourcesZeroResult: sourcesZeroResult,
    queryVariantsRun: nV,
    zeroResultVariants: zeroVariants.length,
    erroredVariants: errVariants.length,
    faultCodes: faultCodes,
    zeroResultDetail: zeroVariants,
    erroredDetail: errVariants,
    broadeningTriggered: broadened,
